async function j(u){ const r=await fetch(u,{signal:AbortSignal.timeout(20000)}); return r.json(); }
const pick=(a,n=6)=>a.filter(x=>/engineer|designer|manager|analyst/i.test(x.title||x.text)).slice(0,n);
for (const s of ["stripe","figma","cloudflare","discord"]) { const d=await j(`https://boards-api.greenhouse.io/v1/boards/${s}/jobs`);
  for (const p of pick(d.jobs)) console.log("gh",s,p.id,"|",p.title,"|",p.location?.name,"|",p.absolute_url,"|",p.updated_at); }
for (const s of ["palantir","spotify"]) { const d=await j(`https://api.lever.co/v0/postings/${s}?mode=json`);
  for (const p of pick(d)) console.log("lv",s,p.id,"|",p.text,"|",p.categories?.location,"|",p.workplaceType,"|",p.categories?.commitment,"|",p.hostedUrl,"|",JSON.stringify(p.salaryRange||null)); }
for (const s of ["notion","linear","ramp"]) { const d=await j(`https://api.ashbyhq.com/posting-api/job-board/${s}?includeCompensation=true`);
  for (const p of pick(d.jobs)) console.log("ab",s,p.id,"|",p.title,"|",p.location,"|",p.workplaceType,p.isRemote,"|",p.employmentType,"|",p.jobUrl,"|",p.compensation?.compensationTierSummary,"|",p.publishedAt); }
EOF
node list.mjs

