import { writeFileSync, mkdirSync } from "node:fs";
const OUT = process.argv[2]; mkdirSync(OUT, { recursive: true });
const D = "2026-10-10";
const SW = "significant_warning", FV = "further_verification", VR = "verified_route";
const src = (company, officialDomain, provider, slug, postingId = null, postingUrl = null) =>
  ({ company, officialDomain, board: provider ? { provider, slug } : null, postingId, postingUrl, checkedAt: D });
const P = {
  stripeAi: ["8144196", "https://stripe.com/jobs/search?gh_jid=8144196"],
  figmaBrand: ["6216211004", "https://boards.greenhouse.io/figma/jobs/6216211004?gh_jid=6216211004"],
  figmaBsa: ["6215865004", "https://boards.greenhouse.io/figma/jobs/6215865004?gh_jid=6215865004"],
  palDefPa: ["a8174f9c-6f46-46b4-8e15-d1ff9e37c9eb", "https://jobs.lever.co/palantir/a8174f9c-6f46-46b4-8e15-d1ff9e37c9eb"],
  palInfra: ["6fe5515f-f677-4d98-8ac2-1775a425f5e7", "https://jobs.lever.co/palantir/6fe5515f-f677-4d98-8ac2-1775a425f5e7"],
  palDefDc: ["1345438c-ebfc-4fa5-b545-30c1414f317c", "https://jobs.lever.co/palantir/1345438c-ebfc-4fa5-b545-30c1414f317c"],
  notionEm: ["3979a6f5-2abb-447b-bd3a-0565b06bae24", "https://jobs.ashbyhq.com/notion/3979a6f5-2abb-447b-bd3a-0565b06bae24"],
  notionInfra: ["42f18ccd-c4c8-4a85-8c1f-de12c575fe87", "https://jobs.ashbyhq.com/notion/42f18ccd-c4c8-4a85-8c1f-de12c575fe87"],
  linearDe: ["f04f398b-6320-499d-8a60-290239d62da8", "https://jobs.ashbyhq.com/linear/f04f398b-6320-499d-8a60-290239d62da8"],
  linearPe: ["12f8f208-0b9c-4569-bb3d-41c8a197029e", "https://jobs.ashbyhq.com/linear/12f8f208-0b9c-4569-bb3d-41c8a197029e"],
  rampFe: ["4e64ab86-4e30-403b-b1b9-41dc052570ce", "https://jobs.ashbyhq.com/ramp/4e64ab86-4e30-403b-b1b9-41dc052570ce"],
  rampAm: ["b9568fb8-a47e-4738-87fb-a6d88c3a505f", "https://jobs.ashbyhq.com/ramp/b9568fb8-a47e-4738-87fb-a6d88c3a505f"],
  rampSec: ["34413f8d-26bf-4bbc-8ade-eb309a0e2245", "https://jobs.ashbyhq.com/ramp/34413f8d-26bf-4bbc-8ade-eb309a0e2245"],
  rampAnd: ["f564dcf9-9390-4a3f-896f-8047a5086040", "https://jobs.ashbyhq.com/ramp/f564dcf9-9390-4a3f-896f-8047a5086040"],
};
const C = {
  stripe: (p) => src("Stripe", "stripe.com", "greenhouse", "stripe", ...(p ?? [])),
  figma: (p) => src("Figma", "figma.com", "greenhouse", "figma", ...(p ?? [])),
  cloudflare: () => src("Cloudflare", "cloudflare.com", "greenhouse", "cloudflare"),
  discord: () => src("Discord", "discord.com", "greenhouse", "discord"),
  palantir: (p) => src("Palantir", "palantir.com", "lever", "palantir", ...(p ?? [])),
  notion: (p) => src("Notion", "notion.com", "ashby", "notion", ...(p ?? [])),
  linear: (p) => src("Linear", "linear.app", "ashby", "linear", ...(p ?? [])),
  ramp: (p) => src("Ramp", "ramp.com", "ashby", "ramp", ...(p ?? [])),
};
const posting = (p) => ({ status: "role_posting_confirmed", url: p[1], host: new URL(p[1]).host });
const careers = { status: "careers_page_only", url: null };
const urlRe = /https?:\/\/[^\s)]+/g;
function make(id, useCase, input, outcome, dimensions, safeRoute, source, syntheticDomains, notes) {
  const forbidden = syntheticDomains;
  const supplied = [...(input.text.match(urlRe) ?? []), ...(input.url ? [input.url] : [])];
  const c = {
    id, useCase, input,
    expected: {
      outcome, dimensions, safeRoute, forbiddenSafeRouteHosts: forbidden,
      flags: { unsafeLink: forbidden.length > 0 || supplied.length > 0, falseAccusation: outcome !== SW },
    },
    source, syntheticDomains, notes,
  };
  writeFileSync(`${OUT}/${id}.json`, JSON.stringify(c, null, 2) + "\n");
}
const none = "none_detected";

// UC1 fake recruiter impersonating a real company
make("uc1-01", "uc1_impersonation", { text: "Hi, this is Corwin Halberg from the Stripe Talent Acquisition team. Your profile matches our AI Engineer opening in Chicago, and we are fast-tracking a few candidates this week. Please complete your application on our candidate portal before Friday: https://stripe-careers-hr.com/apply/ai-engineer-8144196\n\nCorwin Halberg\nTalent Acquisition, Stripe\nc.halberg@stripe-careers-hr.com" },
  SW, { employer: "apparent_impersonation", vacancy: "officially_confirmed", recruiter: "apparent_impersonation", application_link: "lookalike_destination", requests: none, safe_route: "role_posting_confirmed" },
  posting(P.stripeAi), C.stripe(P.stripeAi), ["stripe-careers-hr.com"],
  "Real live Stripe posting. The sender and the apply link both use a brand-plus-keyword combosquat of stripe.com, so the warning comes from the lookalike domain (R1). The Safe Route is the official posting URL from the Greenhouse API, which lives on stripe.com.");
make("uc1-02", "uc1_impersonation", { text: "Hello! I'm Petra Lindqvist-Oyelaran, recruiting for Figma. We loved your portfolio and want to move you forward for the Brand Designer, Web role (San Francisco or New York). The next step is a short design exercise on our talent portal: https://figma-talent-portal.com/brand-designer-web/start\nCreate your candidate profile there and we'll schedule a review.\n\nPetra, Figma Recruiting\nfigma.recruiting.desk@gmail.com" },
  SW, { vacancy: "officially_confirmed", recruiter: "inconsistent_with_practices", application_link: "lookalike_destination", requests: none, safe_route: "role_posting_confirmed" },
  posting(P.figmaBrand), C.figma(P.figmaBrand), ["figma-talent-portal.com"],
  "A webmail sender claiming Figma HR is only a concern (inconsistent_with_practices), not a warning. The warning comes from the combosquat apply link. Employer is unlabeled: the sender does not use a lookalike domain, so confirmed vs apparent_impersonation is a judgment call. figma.com/careers links boards.greenhouse.io/figma.");
make("uc1-03", "uc1_impersonation", { text: "Greetings from Palantir Technologies. My name is Anselm Vardakis, Technical Recruiter. You have been shortlisted for Backend Software Engineer - Defense (Palo Alto, CA, onsite, full-time). Interviews for this role are held over Telegram text chat; add me at @palantir_hr_anselm. Before the chat, upload your resume and availability here: https://secure-hire-docs.com/palantir/backend-defense\n\nAnselm Vardakis | a.vardakis@palantir-recruiting.net" },
  SW, { employer: "apparent_impersonation", vacancy: "officially_confirmed", recruiter: "apparent_impersonation", application_link: "does_not_match", requests: none, safe_route: "role_posting_confirmed" },
  posting(P.palDefPa), C.palantir(P.palDefPa), ["palantir-recruiting.net", "secure-hire-docs.com"],
  "Lookalike sender domain plus an apply link on an unrelated host (does_not_match, because palantir.com and its linked Lever board are established). The chat-only Telegram interview is an extra concern. The Safe Route is the matching Lever posting, linked from palantir.com/careers.");
make("uc1-04", "uc1_impersonation", { text: "Hi, this is Junia Ferraday from Notion HR. We are hiring Remote Data Entry Specialists, $35/hour, flexible hours, no experience needed. The interview is a quick chat on WhatsApp at +1 202-555-0147. Fill in your details to reserve a slot: https://n0tion-careers.com/remote-data-entry" },
  SW, { vacancy: "not_independently_located", recruiter: "inconsistent_with_practices", application_link: "lookalike_destination", requests: none, safe_route: "careers_page_only" },
  careers, C.notion(), ["n0tion-careers.com"],
  "Homoglyph lookalike (0 for o) of notion.com. No matching posting exists on Notion's Ashby board, so the Safe Route is the official careers page only. Employer is unlabeled for the same reason as uc1-02.");
make("uc1-05", "uc1_impersonation", { text: "Hi there, Ramp is growing fast and your experience stood out for our Software Engineer, Frontend role (New York, NY, hybrid). I'm Leontyne Brasher on Ramp's recruiting team. Please submit your application through our hiring portal so I can get you on the calendar.\n\nLeontyne Brasher\nRecruiting | Ramp\nleontyne@ramp-hr-careers.com", url: "https://ramp-hr-careers.com/jobs/software-engineer-frontend" },
  SW, { employer: "apparent_impersonation", vacancy: "officially_confirmed", recruiter: "apparent_impersonation", application_link: "lookalike_destination", requests: none, safe_route: "role_posting_confirmed" },
  posting(P.rampFe), C.ramp(P.rampFe), ["ramp-hr-careers.com"],
  "Combosquat sender and apply URL (supplied as input.url). Real live Ramp posting on the Ashby board linked from ramp.com/careers.");

// UC2 legitimate staffing agency
make("uc2-01", "uc2_staffing_agency", { text: "Hello, I'm Rosalind Achterberg, a technology recruiter with Randstad USA. One of our clients, Notion, is hiring an Engineering Manager, Mobile AI in New York (hybrid). Based on your mobile leadership background, I'd like to set up a 20-minute intro call to see whether you'd like me to present your profile. If you're interested, reply with a few times that work this week.\n\nRosalind Achterberg\nRandstad USA\nr.achterberg@randstadusa.com" },
  VR, { employer: "confirmed", vacancy: "officially_confirmed", recruiter: "verified_intermediary", application_link: "not_provided", requests: none, safe_route: "role_posting_confirmed" },
  posting(P.notionEm), C.notion(P.notionEm), [],
  "Real agency (randstadusa.com, registered 2005) recruiting for a role that is live on Notion's Ashby board. No employer source confirms the partnership, so recruiter is verified_intermediary (neutral). A different sender domain is never a warning here.");
make("uc2-02", "uc2_staffing_agency", { text: "Hi, I'm Teodor Castellane with Robert Half's finance and accounting practice. We're recruiting a Revenue Accounting Specialist for a 6-month contract engagement with Stripe (remote, US hours). The role is filled through Robert Half, so it won't appear on Stripe's own careers site. You can see our open contract roles and apply here: https://www.roberthalf.com/us/en/jobs\n\nTeodor Castellane | Robert Half | t.castellane@roberthalf.com" },
  FV, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "verified_intermediary", application_link: "matches_intermediary_channel", requests: none, safe_route: "careers_page_only" },
  careers, C.stripe(), [],
  "Agency contract role that is not on Stripe's board. A missing posting is not a negative signal. The agency's own site is matches_intermediary_channel and must not become the Safe Route, because it is not employer-controlled.");
make("uc2-03", "uc2_staffing_agency", { text: "Hi, this is Marguerite Solberg-Achebe, a recruiter at TEKsystems. Palantir has engaged us to help source candidates for its Backend Software Engineer - Infrastructure role in New York (hybrid, full-time). The official posting is here: https://jobs.lever.co/palantir/6fe5515f-f677-4d98-8ac2-1775a425f5e7\nYou can apply there directly, or I can submit your profile on your behalf if you prefer.\n\nMarguerite Solberg-Achebe\nTEKsystems\nmsolberg@teksystems.com" },
  VR, { employer: "confirmed", vacancy: "officially_confirmed", recruiter: "verified_intermediary", application_link: "matches_employer_channel", requests: none, safe_route: "role_posting_confirmed" },
  posting(P.palInfra), C.palantir(P.palInfra), [],
  "The agency supplies the real Lever posting. The supplied link may become the Safe Route only because the same URL is independently found via the Lever board linked from palantir.com (G3).");
make("uc2-04", "uc2_staffing_agency", { text: "(LinkedIn InMail) Hi! I'm Bastian Quillfeather, a consultant at Michael Page in the digital and design practice. I'm working on a 9-month contract Senior Product Designer engagement with Figma, remote within the US. Contract roles we place are not always listed on the client's careers page. Would you be open to a quick call? If so, I'll share the full brief and the rate range." },
  FV, { employer: "confirmed", vacancy: "not_independently_located", application_link: "not_provided", requests: none, safe_route: "careers_page_only" },
  careers, C.figma(), [],
  "LinkedIn InMail with no sender domain. Recruiter is unlabeled: verified_intermediary (Michael Page is established) and could_not_verify (the individual cannot be tied to it) are both defensible. Neither is a warning.");

// UC3 real company, nonexistent vacancy
make("uc3-01", "uc3_nonexistent_vacancy", { text: "Hello, Cloudflare's finance team is expanding and we're hiring a Remote Payments Reconciliation Analyst (part-time, 20 hrs/week, $32/hr). I'm Hollis Tremaine, hiring coordinator. Start your application on our onboarding partner's site: https://careerpath-onboarding.com/cloudflare/payments-analyst\nThe form takes 5 minutes.\n\nHollis Tremaine, Hiring Coordinator" },
  SW, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "could_not_verify", application_link: "does_not_match", requests: none, safe_route: "careers_page_only" },
  careers, C.cloudflare(), ["careerpath-onboarding.com"],
  "The warning comes from the apply link on an unrelated host, not from the missing role. The role is absent from Cloudflare's Greenhouse board (checked).");
make("uc3-02", "uc3_nonexistent_vacancy", { text: "Hey! Discord is hiring Community Safety Specialists to review user reports from home (remote, part-time). I'm Wren Castellanos-Moffat from the Discord hiring team. Apply in two minutes at https://jobs-applyhub.net/discord-safety-specialist and we'll be in touch within 24 hours." },
  SW, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "could_not_verify", application_link: "does_not_match", requests: none, safe_route: "careers_page_only" },
  careers, C.discord(), ["jobs-applyhub.net"],
  "Same pattern as uc3-01: an unrelated apply host triggers R1. The role is absent from Discord's Greenhouse board (checked).");
make("uc3-03", "uc3_nonexistent_vacancy", { text: "(LinkedIn message) Hi, I'm Odalys Pemberton, a talent partner hiring for Stripe. We're building out a Payments Operations team and have an opening for a Payments Operations Associate, remote within India. Would you be open to a short call next week to discuss? Let me know a good time." },
  FV, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "could_not_verify", application_link: "not_provided", requests: none, safe_route: "careers_page_only" },
  careers, C.stripe(), [],
  "No link and no requests. The role is not on Stripe's board, which is not a negative signal. Expected further_verification; significant_warning here is a false accusation.");
make("uc3-04", "uc3_nonexistent_vacancy", { text: "Hi, this is Saoirse Valdemar from Figma HR. We have an opening for a Junior UX Researcher (remote, Canada) and your background looks like a fit. Could you send your CV and a few times for a 30-minute video call?\n\nSaoirse Valdemar\nfigma.hr.saoirse@gmail.com" },
  FV, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "inconsistent_with_practices", application_link: "not_provided", requests: none, safe_route: "careers_page_only" },
  careers, C.figma(), [],
  "Webmail while claiming employer HR is a concern, not a warning trigger on its own. A CV is not a sensitive document. The role is absent from Figma's board (checked).");

// UC4 money before onboarding
make("uc4-01", "uc4_money_request", { text: "Congratulations! I'm Fenwick Adeyemi-Strand from Linear's hiring team. After reviewing your portfolio we'd like to move you to onboarding for the Design Engineer (Web & Brand) role (remote, North America). We'll mail you a $4,800 check for your home-office equipment. Deposit it, then pay our approved equipment vendor via Zelle the same day so your laptop ships before your start date. Please keep this between us until onboarding is complete. Continue on Telegram: @linear_onboarding_fenwick" },
  SW, { employer: "confirmed", vacancy: "officially_confirmed", recruiter: "inconsistent_with_practices", application_link: "not_provided", requests: "suspicious_request_detected", safe_route: "role_posting_confirmed" },
  posting(P.linearDe), C.linear(P.linearDe), [],
  "Check deposit and equipment-vendor payment, plus secrecy. The vacancy is real and live, so R1 fires but the Safe Route to the real posting is still shown.");
make("uc4-02", "uc4_money_request", { text: "Hello, you've been selected for a Remote Chat Moderator position with Discord ($25/hr, flexible hours). I'm Imogen Rask, onboarding lead. Before your interview, a one-time $89 training-kit fee is required. Pay in USDT to the wallet address we'll send you on WhatsApp (+1 202-555-0163) and send a screenshot of the payment. Spots are limited and close today." },
  SW, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "inconsistent_with_practices", application_link: "not_provided", requests: "suspicious_request_detected", safe_route: "careers_page_only" },
  careers, C.discord(), [],
  "Crypto fee before the interview, plus urgency. The role is absent from Discord's board (checked).");
make("uc4-03", "uc4_money_request", { text: "Hi, I'm Calloway Brennick from Ramp's talent team regarding the Account Manager | Commercial role in New York. You've passed the screening stage. To schedule your interview we need you to cover the $65 background-check fee. Please buy a $65 Apple gift card and email the card number and PIN to ramp.talentteam.calloway@outlook.com within 24 hours." },
  SW, { employer: "confirmed", vacancy: "officially_confirmed", recruiter: "inconsistent_with_practices", application_link: "not_provided", requests: "suspicious_request_detected", safe_route: "role_posting_confirmed" },
  posting(P.rampAm), C.ramp(P.rampAm), [],
  "Gift-card fee before the interview, from webmail. Real live posting, so the Safe Route is shown alongside the warning.");

// UC5 early sensitive-document request
make("uc5-01", "uc5_sensitive_documents", { text: "Hi, I'm Thaddeus Moreau-Ilves, recruiter for Cloudflare. We'd like to interview you for a Remote Technical Support Associate role. Before we schedule the interview, please send a clear photo of your passport and your bank account number and IFSC code here on WhatsApp so payroll can be set up in advance. Message me at +1 202-555-0182." },
  SW, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "inconsistent_with_practices", application_link: "not_provided", requests: "suspicious_request_detected", safe_route: "careers_page_only" },
  careers, C.cloudflare(), [],
  "Passport and bank details requested before any interview, over an unverified channel. The role is absent from Cloudflare's board (checked).");
make("uc5-02", "uc5_sensitive_documents", { text: "Hello, thank you for your interest in Discord. I'm Linnea Barrowcliffe from the people team. For the Trust & Safety Associate (Remote) role, we verify identity before the first interview. Please reply with your Social Security number, date of birth, and a photo of the front and back of your driver's license.\n\nLinnea Barrowcliffe\ndiscord.peopleteam.linnea@gmail.com" },
  SW, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "inconsistent_with_practices", application_link: "not_provided", requests: "suspicious_request_detected", safe_route: "careers_page_only" },
  careers, C.discord(), [],
  "SSN and driver's license requested before an interview, from webmail. The role is absent from Discord's board (checked).");
make("uc5-03", "uc5_sensitive_documents", { text: "Hi, congratulations again on accepting our offer for the Treasury Analyst role in Bengaluru. I'm Ingrid Castellvi from Stripe's People team. To complete your onboarding paperwork, please submit your PAN details and a copy of your Aadhaar through the secure onboarding portal invitation you will receive from our HR system this week. Please don't send documents over email. Reach out if anything is unclear.\n\nIngrid Castellvi\nPeople Team, Stripe\ni.castellvi@stripe.com" },
  FV, { employer: "confirmed", vacancy: "not_independently_located", recruiter: "consistent_with_employer", application_link: "not_provided", requests: "needs_confirmation", safe_route: "careers_page_only" },
  careers, C.stripe(), [],
  "Post-offer tax-ID request from the official domain (stripe.com enforces DMARC p=reject) at a plausible stage: needs_confirmation, not a warning. The role is filled, so it is no longer on the board, which keeps this at R3 instead of R2.");

// UC6 conflicting terms vs the official listing
make("uc6-01", "uc6_conflicting_terms", { text: "(LinkedIn message) Hi, I'm Auberon Kestell, a recruiter working on Ramp's security hiring. We have a Security Engineer, Cloud opening that is fully remote from anywhere in the US, with a salary range of $95K-$115K. Would you like to set up a call this week?" },
  FV, { employer: "confirmed", vacancy: "conflicting_information", recruiter: "could_not_verify", application_link: "not_provided", requests: none, safe_route: "careers_page_only" },
  careers, C.ramp(P.rampSec), [],
  "The official posting is New York (HQ), hybrid, $211.4K-$290.6K. The message claims fully remote at $95K-$115K, so workplace and compensation band (more than 20% apart) are material diffs. The Safe Route is careers_page_only because vacancy is not officially_confirmed.");
make("uc6-02", "uc6_conflicting_terms", { text: "Hello, I'm Rosamund Tegwyn from Palantir recruiting. We're hiring a Backend Software Engineer - Defense for our Washington, D.C. team. This is a fully remote, 1099 contract position for 6 months. Let me know if you'd like to discuss." },
